def do_GET(self) -> None:
    parts = urlsplit(self.path)
    path = parts.path

    operator = self._operator()
    if operator is None:
        return
    self._operator_id = operator

    operation_match = _OPERATIONS_PATH_RE.match(path)
    if operation_match is not None:
        self._get_operation(
            operation_match.group(1), parts, operator
        )
        return

    if path == _AUDIT_PATH:
        # Audit failures are 500, not audited themselves.
        try:
            self._get_audit(parts, operator)
        except LedgerError as exc:
            self._server_error(exc)
        return

    if path == _AUDIT_VERIFY_PATH:
        try:
            self._get_audit_verify(parts, operator)
        except LedgerError as exc:
            self._server_error(exc)
        return

    if path == _KEYS_PATH:
        try:
            self._list_keys(parts, operator)
        except LedgerError as exc:
            self._server_error(exc)
        return

    if path == _POLICY_PATH:
        try:
            self._get_policy(parts)
        except LedgerError as exc:
            self._server_error(exc)
        return

    if path == _PROVIDER_STATUS_PATH:
        self._provider_status()
        return

    try:
        versions_match = _VERSIONS_PATH_RE.match(path)
        if versions_match is not None:
            self._get_versions(
                versions_match.group(1), parts, operator
            )
            return

        version_status_match = _VERSION_STATUS_PATH_RE.match(path)
        if version_status_match is not None:
            self._get_version_status(
                version_status_match.group(1),
                version_status_match.group(2),
                parts, operator,
            )
            return

        version_match = _VERSION_PATH_RE.match(path)
        if version_match is not None:
            self._get_version(
                version_match.group(1), version_match.group(2),
                parts, operator,
            )
            return

        current_match = _CURRENT_PATH_RE.match(path)
        if current_match is not None:
            self._get_current(
                current_match.group(1), parts, operator
            )
            return

        status_match = _STATUS_PATH_RE.match(path)
        if status_match is not None:
            self._get_status(
                status_match.group(1), parts, operator
            )
            return

        key_match = _KEY_PATH_RE.match(path)
        if key_match is not None:
            self._get_key(key_match.group(1), parts, operator)
            return
    except LedgerError as exc:
        self._server_error(exc)
        return

    self._send_json(404, {"error": "not found" })

def _reject_read(self, tenant_id, key_id, status, message) -> None:
    if not self._record_attempt(
        tenant_id, key_id, audit_mod.ACTION_READ,
        audit_mod.OUTCOME_REJECTED,
    ):
        return
    self._send_json(status, {"error": message})

def _get_key(self, key_id: str, parts, operator: str) -> None:
    tenant_id = self._tenant(parts)
    if tenant_id is None:
        return
    if self._bad_key_id(key_id):
        return
    if not self._enforce(
        tenant_id, key_id, audit_mod.ACTION_READ, operator
    ):
        return
    record = store.get(key_id, tenant_id)
    if record is None:
        # Same status whether the key is missing or owned by another
        # tenant: never confirm the existence of another tenant's key.
        self._reject_read(tenant_id, key_id, 404, "key not found")
        return
    if not self._record_attempt(
        tenant_id, key_id, audit_mod.ACTION_READ,
        audit_mod.OUTCOME_SUCCESS,
    ):
        return
    self._send_json(200, record.to_get_response())

def _get_version(self, key_id: str, raw_version: str, parts,
                 operator: str) -> None:
    tenant_id = self._tenant(parts)
    if tenant_id is None:
        return
    if self._bad_key_id(key_id):
        return
    version = self._parse_version(raw_version)
    if version is None:
        # Bad version parameter: tenant and key are known, so the
        # rejection is visible to them.
        self._reject_read(
            tenant_id, key_id, 400,
            "field version must be a positive integer",
        )
        return
    if not self._enforce(
        tenant_id, key_id, audit_mod.ACTION_READ, operator
    ):
        return
    result = store.get_version(
        key_id, tenant_id, version, strict=True
    )
    if result is None:
        # Unknown key, unknown version and cross-tenant access are
        # indistinguishable, all 404.
        self._reject_read(
            tenant_id, key_id, 404, "version not found"
        )
        return
    if not self._record_attempt(
        tenant_id, key_id, audit_mod.ACTION_READ,
        audit_mod.OUTCOME_SUCCESS,
    ):
        return
    _record, ver = result
    self._send_json(200, ver.to_version_response(key_id))

def _get_version_status(self, key_id: str, raw_version: str, parts,
                       operator: str) -> None:
    """GET /v1/keys/{key_id}/versions/{version}/status.

    Authorized as ``read`` like the other key/version reads. A bad
    key/version parameter is a 400 naming the field (with a rejected
    read event, like GET .../versions/{v}); an unknown or
    cross-tenant key/version is an indistinct 404. A successful read
    is ``200`` with keys in order
    ``key_id,version,status,reason,operator,revoked_at``; an active
    version carries null for the three revocation fields.
    """
    tenant_id = self._tenant(parts)
    if tenant_id is None:
        return
    if self._bad_key_id(key_id):
        return
    # Read conventions (GET .../versions/{v}): a bad version is a
    # 400 naming the field with one read/rejected event, sent once.
    if not _POSITIVE_INT_RE.fullmatch(raw_version) or int(
        raw_version
    ) < 1:
        self._reject_read(
            tenant_id, key_id, 400,
            "field version must be a positive integer",
        )
        return
    version = int(raw_version)
    if not self._enforce(
        tenant_id, key_id, audit_mod.ACTION_READ, operator
    ):
        return
    result = store.get_version(key_id, tenant_id, version)
    if result is None:
        self._reject_read(
            tenant_id, key_id, 404, "version not found"
        )
        return
    record, ver = result
    if record.status == "revoked":
        # Whole-key revocation outranks a version state: the version
        # status read defers to it with a 409, like a version revoke.
        self._reject_read(tenant_id, key_id, 409, "key is revoked")
        return
    if not self._record_attempt(
        tenant_id, key_id, audit_mod.ACTION_READ,
        audit_mod.OUTCOME_SUCCESS,
    ):
        return
    self._send_json(200, ver.to_version_status_response(key_id))

def _get_versions(self, key_id: str, parts, operator: str) -> None:
    """GET /v1/keys/{key_id}/versions: the key's full history.

    Every committed version is returned in ascending version order;
    each item merges the single-version read fields with the version
    status fields and flags ``current``. A whole-key revocation does
    not hide the history: its revocation facts project onto every
    item. The single tenant comes from one source (single header or
    single parameter); ``limit`` is 1-1000 (default 100) and
    ``cursor`` follows the signed snapshot cursor rules. All
    parameter failures (including a malformed key_id or cursor) are
    400s with no audit event -- only a missing/conflicting tenant
    source records ``tenant_conflict`` as usual -- and validation
    precedes authorization. A policy denial is 403 with one
    ``read/rejected`` event carrying the key_id; an unknown or
    cross-tenant key is an indistinct 404; success is 200 with one
    ``read/success`` event and ``{items,next_cursor}``.
    """
    tenant_id = self._audit_tenant(parts)
    if tenant_id is None:
        return
    if not is_valid_key_id(key_id):
        self._bad_request("field key_id must be a UUID4")
        return
    qs = parse_qs(parts.query, keep_blank_values=True)

    limit = 100
    values, errored = self._single_param(qs, "limit")
    if errored:
        return
    if values:
        raw_limit = values[0]
        if not _POSITIVE_INT_RE.fullmatch(raw_limit):
            self._bad_request(
                "field limit must be an integer between 1 and 1000"
            )
            return
        limit = int(raw_limit)
        if not 1 <= limit <= 1000:
            self._bad_request(
                "field limit must be an integer between 1 and 1000"
            )
            return

    values, errored = self._single_param(qs, "cursor")
    if errored:
        return
    cursor = values[0] if values else None
    if cursor is not None and not cursor:
        self._bad_request("field cursor must be a non-empty string")
        return
    # A duplicate/empty cursor is rejected above; a tampered or
    # otherwise undecodable cursor is a parameter 400 as well, so
    # verify the signature before consulting the policy.
    if cursor is not None:
        try:
            store.audit._decode_cursor(cursor)
        except InvalidCursor:
            self._bad_request("invalid or expired cursor")
            return

    if not self._enforce(
        tenant_id, key_id, audit_mod.ACTION_READ, operator
    ):
        return

    try:
        page = store.versions_page(
            key_id, tenant_id, limit=limit, cursor=cursor,
            strict=True,
        )
    except InvalidCursor:
        self._bad_request("invalid or expired cursor")
        return
    if page is None:
        self._reject_read(
            tenant_id, key_id, 404, "key not found"
        )
        return
    if not self._record_attempt(
        tenant_id, key_id, audit_mod.ACTION_READ,
        audit_mod.OUTCOME_SUCCESS,
    ):
        return
    self._send_json(
        200,
        {
            "items": page.items,
            "next_cursor": page.next_cursor,
        },
    )

def _get_current(self, key_id: str, parts, operator: str) -> None:
    tenant_id = self._tenant(parts)
    if tenant_id is None:
        return
    if self._bad_key_id(key_id):
        return
    if not self._enforce(
        tenant_id, key_id, audit_mod.ACTION_READ, operator
    ):
        return
    record = store.get(key_id, tenant_id)
    if record is None:
        self._reject_read(tenant_id, key_id, 404, "key not found")
        return
    if not self._record_attempt(
        tenant_id, key_id, audit_mod.ACTION_READ,
        audit_mod.OUTCOME_SUCCESS,
    ):
        return
    self._send_json(200, record.current.to_version_response(key_id))

def _single_param(self, qs, name):
    """Return (values, error_sent). Exactly one value or 400."""
    values = qs.get(name, [])
    if len(values) > 1:
        self._bad_request("duplicate %s parameter" % name)
        return None, True
    return values, False

def _get_audit(self, parts, operator: str) -> None:
    tenant_id = self._audit_tenant(parts)
    if tenant_id is None:
        return
    qs = parse_qs(parts.query, keep_blank_values=True)

    since = None
    until = None
    values, errored = self._single_param(qs, "since")
    if errored:
        return
    if values:
        since = values[0]
        try:
            since = audit_mod.canonical_rfc3339(since)
        except ValueError:
            self._bad_request(
                "field since must be an RFC3339 timestamp"
            )
            return
    values, errored = self._single_param(qs, "until")
    if errored:
        return
    if values:
        until = values[0]
        try:
            until = audit_mod.canonical_rfc3339(until)
        except ValueError:
            self._bad_request(
                "field until must be an RFC3339 timestamp"
            )
            return
    if since is not None and until is not None and since > until:
        self._bad_request(
            "field until must not be earlier than since"
        )
        return

    values, errored = self._single_param(qs, "key_id")
    if errored:
        return
    key_id = values[0] if values else None
    if key_id is not None and not is_valid_key_id(key_id):
        # An illegal identifier is a tenant_conflict event, like any
        # other malformed tenant/key parameter.
        if self._record_conflict():
            self._bad_request("field key_id must be a UUID4")
        return

    values, errored = self._single_param(qs, "action")
    if errored:
        return
    action = values[0] if values else None
    if action is not None and action not in audit_mod.ACTIONS:
        self._bad_request(
            "field action must be one of: %s"
            % ", ".join(audit_mod.ACTIONS)
        )
        return

    values, errored = self._single_param(qs, "operation_id")
    if errored:
        return
    operation_id = values[0] if values else None
    if operation_id is not None and not is_valid_key_id(
        operation_id
    ):
        # An empty, duplicated or malformed operation_id is a plain
        # parameter 400 naming the field: it precedes the policy check
        # and writes no audit event (only a missing/conflicting
        # tenant source records tenant_conflict).
        self._bad_request("field operation_id must be a UUID4")
        return

    values, errored = self._single_param(qs, "outcome")
    if errored:
        return
    outcome = values[0] if values else None
    if outcome is not None and outcome not in audit_mod.OUTCOMES:
        # Case-sensitive; an empty, whitespace-padded or cased
        # variant is a plain parameter 400 naming the field, checked
        # before the policy decision and without any audit write.
        self._bad_request(
            "field outcome must be one of: %s"
            % ", ".join(audit_mod.OUTCOMES)
        )
        return

    limit = 100
    values, errored = self._single_param(qs, "limit")
    if errored:
        return
    if values:
        raw_limit = values[0]
        if not _POSITIVE_INT_RE.fullmatch(raw_limit):
            self._bad_request(
                "field limit must be an integer between 1 and 1000"
            )
            return
        limit = int(raw_limit)
        if not 1 <= limit <= 1000:
            self._bad_request(
                "field limit must be an integer between 1 and 1000"
            )
            return

    values, errored = self._single_param(qs, "cursor")
    if errored:
        return
    cursor = values[0] if values else None

    # Parameter validation (400) precedes authorization; a policy
    # rejection of an audit query is recorded with the original
    # action ("audit") and outcome rejected, key_id null.
    if not self._enforce(
        tenant_id, None, audit_mod.ACTION_AUDIT, operator
    ):
        return

    try:
        page = store.audit.query(
            tenant_id,
            key_id=key_id,
            action=action,
            operation_id=operation_id,
            outcome=outcome,
            since=since,
            until=until,
            limit=limit,
            cursor=cursor,
        )
    except InvalidCursor:
        self._bad_request("invalid or expired cursor")
        return
    self._send_json(
        200,
        {
            "events": [e.to_response() for e in page.events],
            "next_cursor": page.next_cursor,
        },
    )

def _empty_request_body(self) -> bool:
    """Validate a GET body as absent or an empty JSON object."""
    try:
        length = int(self.headers.get("Content-Length", 0))
    except ValueError:
        self._bad_request("invalid Content-Length")
        return False
    raw = self.rfile.read(length) if length > 0 else b""
    if not raw:
        return True
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError):
        self._bad_request("request body must be valid JSON")
        return False
    if not isinstance(payload, dict):
        self._bad_request("request body must be a JSON object")
        return False
    if payload:
        extra = next(iter(payload))
        self._bad_request(
            "field %s is not accepted by this endpoint" % extra
        )
        return False
    return True

def _get_audit_verify(self, parts, operator: str) -> None:
    tenant_id = self._audit_tenant(parts)
    if tenant_id is None:
        return
    if not self._empty_request_body():
        return
    if not self._enforce(
        tenant_id, None, audit_mod.ACTION_AUDIT, operator
    ):
        return
    self._send_json(200, store.audit.verify(tenant_id))

